"""日程 JavaScript の部品を、既存のブラウザ入口へ結合する。"""

from pathlib import Path


BASE_DIR = Path(__file__).resolve().parents[1]
PARTS = ("bootstrap", "dates", "state", "api", "render", "forms", "main")


def build():
    source_dir = BASE_DIR / "static" / "js" / "schedule"
    parts = [
        (source_dir / f"{name}.js").read_text(encoding="utf-8")
        for name in PARTS
    ]
    output = BASE_DIR / "static" / "schedule_board.js"
    # 一つの関数スコープを維持し、変数・関数の共有と初期化順を変えない。
    output.write_text(
        "// Generated by scripts/build_schedule_js.py; edit static/js/schedule/.\n"
        "(function () {\n" + "\n".join(parts) + "})();\n",
        encoding="utf-8",
    )
    return output


if __name__ == "__main__":
    print(build())
